/*
 * Zephyr ADC example – read a single channel and print the value in millivolts.
 *
 * Board: nrf52840dk/nrf52840
 *
 * The device tree must contain a node that points to the ADC channel you want
 * to use, e.g. in an overlay:
 *
 *   &adc0 {
 *       zephyr,user {
 *           io-channels = <&adc0 1>;   // channel 1 of ADC0
 *           input-positive = <NRF_SAADC_INPUT_AIN1>;
 *           reference = <NRF_SAADC_REF_VDD_4>;
 *           acquisition-time = <NRF_SAADC_ACQ_TIME(10)>;
 *       };
 *   };
 *
 * The code below expects such a node at the path /zephyr_user.
 */

#include <zephyr/kernel.h>
#include <zephyr/drivers/adc.h>
#include <zephyr/sys/printk.h>

/* Obtain the ADC DT spec for the node /zephyr_user */
static const struct adc_dt_spec adc_spec = ADC_DT_SPEC_GET(DT_PATH(zephyr_user));

void main(void)
{
    int ret;

    /* Verify the ADC device is ready */
    if (!device_is_ready(adc_spec.dev)) {
        printk("ADC device not ready\n");
        return;
    }

    /* Configure the ADC channel described by the DT spec */
    ret = adc_channel_setup_dt(&adc_spec);
    if (ret < 0) {
        printk("Failed to set up ADC channel (err %d)\n", ret);
        return;
    }

    /* Buffer to hold the raw ADC sample */
    static int16_t sample_buf[1];

    /* ADC sequence definition */
    struct adc_sequence sequence = {
        .channels    = BIT(adc_spec.channel_id),
        .buffer      = sample_buf,
        .buffer_size = sizeof(sample_buf),
        .resolution  = adc_spec.resolution,
    };

    while (1) {
        /* Perform the ADC conversion */
        ret = adc_read_dt(&adc_spec, &sequence);
        if (ret < 0) {
            printk("ADC read error (err %d)\n", ret);
            goto sleep;
        }

        /* Convert raw sample to millivolts */
        int32_t millivolts;
        ret = adc_raw_to_millivolts_dt(&adc_spec, sample_buf[0], &millivolts);
        if (ret < 0) {
            printk("Conversion to mV failed (err %d)\n", ret);
            goto sleep;
        }

        /* Print the result */
        printk("ADC value: %d mV\n", millivolts);

sleep:
        /* Wait 1 second before the next sample */
        K_MSLEEP(1000);
    }
}
